      SUBROUTINE UPSIGCC     UPDATE BEAM MATRIX AND ITS PARTIAL DERIVATIVESCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM7C.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'R2VT.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'      DIMENSION      SVS(6,6)C ----------------------------------------------------------------------CC     CALCULATION OF BEAM PARAMETERSC      IF (NM .GT. 0) CALL UPMIS      IF (.NOT. RECENT) CALL BEAMCC     PARTIAL DERIVATIVES OF BEAM PARAMETERSC      IF (NV1 .LT. 1) GO TO 110      CALL CAB(RS,RC2,SI)      DO 100 N = 1, NV1, 1CC     TRANSFORMATION OF PARTIAL DERIVATIVES OF PREVIOUS BEAM PARAMETERSC      IF (SVP(N)) THEN        DO 50 JU = 1, 6        DO 50 KU = 1, 6        SVS(JU,KU) = SV(JU,KU,N)   50   CONTINUE        CALL CAB(RT,RC2,SVS)        CALL CABT(SVS,RC2,RT)        DO 60 JU = 1, 6        DO 60 KU = 1, 6        SV(JU,KU,N) = SVS(JU,KU)   60   CONTINUE      ENDIFCC     EFFECT OF DERIVATIVE OF R MATRIX ON PREVIOUS BEAM PARAMETERSC      IF (.NOT. R2VP(N)) GO TO 100      DO 70 JK = 1, 36      R2VTL(JK) = R2VL(JK,N)   70 CONTINUE      CALL CABT(RT,R2VT,RS)C      IF (.NOT. SVP(N)) THEN        DO 80 JU = 1, 6        DO 80 KU = 1, 6        SV(JU,KU,N) = RT(JU,KU) + RT(KU,JU)   80   CONTINUE      ELSEC        DO 90 JU = 1, 6        DO 90 KU = 1, JU        SV(JU,KU,N) = SV(JU,KU,N) + RT(JU,KU) + RT(KU,JU)   90   CONTINUE      ENDIFC      CONTINUE      SVP(N)  =  .TRUE.  100 CONTINUECC     NEW BEAM PARAMETERSC  110 DO 120 JU = 1, 6  120 CO(JU) = CEN(JU)      DO 130 JU = 1, 6      DO 130 KU = 1, 6      SI(JU,KU) = SIT(JU,KU)  130 CONTINUE      PSIX1 = PSIX      PSIY1 = PSIY      RETURN      END